const $=id=>document.getElementById(id),names={ferrari:'Ferrari 458',porsche:'Porsche 911 Turbo S','porsche-reference':'Porsche 911 Turbo S · 원본 텍스처'},views={garage:'같은 차고 · 같은 조명 · 실차 전장 기준',cockpit:'원본 실내 · 주행 정보와 거울 영상은 연결 전',wheels:'분리한 네 바퀴 · 앞바퀴 조향과 네 바퀴 굴림',steering:'분리한 운전대 · 고정된 기둥과 계기판은 제외'};
