async function show(key,{count=1,mixed=false}={}){loading=true;controls();try{const template=await ensure(key),other=mixed?await ensure('ferrari'):null;removeActors();addActor(template,[0,.24,-110]);if(count===4){for(const [i,pos] of [[-3.5,.24,-105],[0,.24,-103],[3.5,.24,-105]].entries())addActor(mixed&&i<2?other:template,pos);}for(const a of actors)appearance(a,$('paint').value,$('rim').value);refreshPose();cameraPose();renderer.render(scene,camera);$('car-label').textContent=mixed?'Ferrari × 2 + Porsche × 2':names[key]+(count===4?' × 4':'');$('view-label').textContent=views[view];$('status').textContent=key==='porsche-reference'?'원본 텍스처예요. 스마트폰용과 화질을 비교해 보세요.':'준비됐어요. 차량과 보기를 바꿔 가며 확인해 보세요.';}finally{loading=false;controls();report();}}
function setView(value){view=value;refreshPose();cameraPose();$('view-label').textContent=views[view];controls();renderer.render(scene,camera);report();}
function rotate(delta){if(view!=='garage'||loading||measuring)return;angle+=delta;refreshPose();report();}
for(const button of document.querySelectorAll('[data-car]'))button.onclick=async()=>{vehicle=button.dataset.car;try{await show(vehicle==='porsche'?quality:'ferrari');}catch(e){fail(e);}};
