for(const button of document.querySelectorAll('[data-view]'))button.onclick=()=>setView(button.dataset.view);
for(const id of ['paint','rim'])$(id).onchange=()=>{for(const actor of actors)appearance(actor,$('paint').value,$('rim').value);renderer.render(scene,camera);report();};
$('steer').oninput=e=>{steer=Number(e.target.value)/100;refreshPose();controls();report();};$('roll').onclick=()=>{rolling=!rolling;controls();report();};$('reset').onclick=()=>{steer=roll=angle=0;rolling=false;$('steer').value='0';refreshPose();cameraPose();controls();report();};$('left').onclick=()=>rotate(-Math.PI/4);$('right').onclick=()=>rotate(Math.PI/4);bindDragRotation($('stage'),rotate,{enabled:()=>ready&&!loading&&!measuring&&view==='garage'});
