async function sample(){let start=0,previous=0;const intervals=[],submit=[];while(true){const now=await new Promise(requestAnimationFrame);if(abort||document.hidden)throw Error('cancelled');if(!start)start=now;roll+=previous?Math.min(.05,(now-previous)/1000)*6:0;refreshPose();const before=performance.now();renderer.render(scene,camera);const elapsed=performance.now()-before;if(previous&&now-start>=1200){intervals.push(now-previous);submit.push(elapsed);}previous=now;if(now-start>=6200)break;}const sum=intervals.reduce((a,b)=>a+b,0);report();return{fps:intervals.length*1000/sum,frames:intervals.length,medianMs:percentile(intervals,.5),p95Ms:percentile(intervals,.95),over33ms:intervals.filter(x=>x>33.4).length,submitMedianMs:percentile(submit,.5),calls:renderer.info.render.calls,triangles:renderer.info.render.triangles,stage:{width:renderer.domElement.clientWidth,height:renderer.domElement.clientHeight,pixelRatio:renderer.getPixelRatio()}};}
const profiles=[{name:'페라리 외관 1대',key:'ferrari',count:1,view:'garage'},{name:'포르쉐 외관 1대',key:'porsche',count:1,view:'garage'},{name:'페라리 외관 4대',key:'ferrari',count:4,view:'garage'},{name:'포르쉐 외관 4대',key:'porsche',count:4,view:'garage'},{name:'페라리·포르쉐 혼합 4대',key:'porsche',count:4,mixed:true,view:'garage'},{name:'페라리 운전석',key:'ferrari',count:1,view:'cockpit'},{name:'포르쉐 운전석',key:'porsche',count:1,view:'cockpit'}];
