async function boot(){renderer=new T.WebGLRenderer({canvas:$('world'),antialias:true,powerPreference:'high-performance'});const reviewRatio=Number(new URLSearchParams(location.search).get('review-dpr'));renderer.setPixelRatio(Math.min(reviewRatio>0?reviewRatio:devicePixelRatio,1.5));renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=.85;scene=new T.Scene();scene.background=new T.Color('#101e34');scene.fog=new T.FogExp2('#1b2e47',.003);camera=new T.PerspectiveCamera(40,1,.04,700);shared=await loadShared();scene.environment=shared.assets.environment;scene.environmentIntensity=1;const garage=buildGarage(scene);garage.traverse(o=>{if(o.isLight)o.intensity=0;});garage.userData.sign.visible=false;shadowGeometry=new T.PlaneGeometry(3.1,5.25);shadowMaterial=new T.MeshBasicMaterial({map:shared.assets.shadow,blending:T.MultiplyBlending,transparent:true,depthWrite:false,toneMapped:false,premultipliedAlpha:true,opacity:.8});await ensure('ferrari');ready=true;await show('porsche');resize();new ResizeObserver(resize).observe($('stage'));addEventListener('resize',resize);function frame(now){if(!measuring&&!loading){if(rolling&&last){roll+=Math.min(.05,(now-last)/1000)*6;refreshPose();}renderer.render(scene,camera);if(now-lastReport>500){report();lastReport=now;}}last=now;requestAnimationFrame(frame);}requestAnimationFrame(frame);report();}
